// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.designsystemimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.unit.dp/** * NOUS — Design tokens. * * Single source of truth for colors, used by both :feature:ui (NOUSTheme) * and any module that needs brand colors. Avoids hardcoding hex everywhere. * * Palette inspired by: *   - SpaceX website (near-black background, white text, single accent) *   - Linear app (muted secondary text, subtle dividers) *   - Anthropic Claude (warm minimalism, but we go cooler) * * Color usage rules: *   - Background: [BackgroundPrimary] (near-black) *   - Surface (cards, sheets): [SurfacePrimary] (slightly lighter) *   - Surface variant (selected states): [SurfaceVariant] *   - Text primary: [TextPrimary] (near-white) *   - Text secondary: [TextSecondary] (muted blue-gray) *   - Text disabled: [TextDisabled] *   - Accent (CTA, links, focus): [AccentCyan] *   - Accent secondary (decorative): [AccentPurple] *   - Warning: [AccentAmber] *   - Error: [AccentRed] *   - Success: [AccentGreen] */object NousColors {    // Backgrounds    val BackgroundPrimary = Color(0xFF050608)    val BackgroundSecondary = Color(0xFF0D0F14)    val BackgroundTertiary = Color(0xFF161922)    // Surfaces    val SurfacePrimary = Color(0xFF0D0F14)    val SurfaceVariant = Color(0xFF1A1F28)    val SurfaceElevated = Color(0xFF222831)    // Text    val TextPrimary = Color(0xFFE8EBF0)    val TextSecondary = Color(0xFF9BA3B4)    val TextDisabled = Color(0xFF5A6478)    val TextInverse = Color(0xFF050608)    // Accents    val AccentCyan = Color(0xFF00E5FF)        // signature    val AccentCyanDim = Color(0xFF003744)    val AccentPurple = Color(0xFF7C4DFF)    val AccentPurpleDim = Color(0xFF2A1457)    val AccentAmber = Color(0xFFFFB300)    val AccentAmberDim = Color(0xFF4D3500)    val AccentRed = Color(0xFFFF3D57)    val AccentRedDim = Color(0xFF4D0008)    val AccentGreen = Color(0xFF00E676)    val AccentGreenDim = Color(0xFF003D1F)    // Borders / dividers    val Outline = Color(0xFF2A3140)    val OutlineVariant = Color(0xFF1A1F28)    // Scrim    val Scrim = Color(0xCC000000)  // 80% black}/** * NOUS — Motion tokens. * * Animation durations and easing curves. Used by all Compose animations for * consistency. * * Inspired by Material Motion, but tuned for the "fast + precise" feel of * NOUS (more like Linear than Material). */object NousMotion {    // Durations (ms)    const val DurationInstant = 0    const val DurationFast = 150    const val DurationMedium = 300    const val DurationSlow = 500    const val DurationGlacial = 1000    // Easing (Compose easing objects)    val EasingEmphasized = androidx.compose.animation.core.Easing { fraction ->        // Material Emphasized Decelerate        val c = 1.70158f        val x = fraction - 1        1 + (x * x * ((c + 1) * x + c))    }    val EasingStandard = androidx.compose.animation.core.Easing { fraction ->        // Material Standard        val t = fraction - 1        1 + t * t * t    }    val EasingLinear = androidx.compose.animation.core.LinearEasing}/** * NOUS — Spacing tokens. * * Used for consistent padding, margins, gaps. Powers of 2 for visual rhythm. */object NousSpacing {    val xs = 4.dp    val sm = 8.dp    val md = 12.dp    val lg = 16.dp    val xl = 24.dp    val xxl = 32.dp    val xxxl = 48.dp    val huge = 64.dp}